// Cold-cache dev server start and first-load timing for the perf scripts.
import { spawn } from 'node:child_process';
import { chromium } from 'playwright';

export async function startDevServer() {
  const server = spawn('pnpm', ['vite', '--force', '--port', '5179'], { stdio: 'pipe' });
  await new Promise((resolve) => server.stdout.on('data', (b) => String(b).includes('ready in') && resolve()));
  return server;
}

export async function timeFirstLoad(server) {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const start = performance.now();
  await page.goto('http://localhost:5179', { waitUntil: 'load' });
  const seconds = ((performance.now() - start) / 1000).toFixed(1);
  await browser.close();
  server.kill();
  return `${seconds}s`;
}

